mkdir -p /root/output && python - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
ws=wb['Task']
print('\nTask!D12:D17, D19:D24, D26:D31 series codes:')
for start,end in [(12,17),(19,24),(26,31)]:
    for r in range(start,end+1):
        print(f'Task!D{r} = {ws[f"D{r}"].value!r}')
    print('-')
print('\nTask row 10 H:L years:')
for c in range(8,13):
    print(f'Task!{get_column_letter(c)}10 = {ws.cell(10,c).value!r}')
print('\nTask H35:H40 labels and D35:D40 region labels:')
for r in range(35,41):
    print(f'Task!H{r}={ws[f"H{r}"].value!r}; Task!D{r}={ws[f"D{r}"].value!r}')
print('\nTask H42:H47 statistic labels:')
for r in range(42,48):
    print(f'Task!H{r} = {ws[f"H{r}"].value!r}')
print('\nTask H50 label area:')
for cell in ['D50','E50','F50','G50','H50']:
    print(f'Task!{cell} = {ws[cell].value!r}')

wd=wb['Data']
print('\nData rows 21 through 38 (non-empty values / focus first columns and years):')
for r in range(21,39):
    vals=[]
    for c in range(1, min(wd.max_column,20)+1):
        v=wd.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}={v!r}')
    print(f'Row {r}: ' + '; '.join(vals))
print('\nData possible year header rows around 1:25:')
for r in range(1,26):
    vals=[]
    year_count=0
    for c in range(1,wd.max_column+1):
        v=wd.cell(r,c).value
        if isinstance(v,int) and 1900<=v<=2100:
            year_count+=1
        elif isinstance(v,str) and v.strip().isdigit() and 1900<=int(v.strip())<=2100:
            year_count+=1
    if year_count:
        for c in range(1,wd.max_column+1):
            v=wd.cell(r,c).value
            if v is not None:
                vals.append(f'{get_column_letter(c)}={v!r}')
        print(f'Row {r} ({year_count} years): ' + '; '.join(vals))

# Identify series code column in rows 21-38: compare Task codes.
task_codes=[ws[f'D{r}'].value for block in [(12,17),(19,24),(26,31)] for r in range(block[0],block[1]+1)]
print('\nTask codes for matching:', task_codes)
for c in range(1,wd.max_column+1):
    col_vals=[wd.cell(r,c).value for r in range(21,39)]
    overlap=sum(1 for v in col_vals if v in task_codes)
    nonempty=sum(1 for v in col_vals if v is not None)
    if overlap or nonempty>=10:
        print(f'Data column {get_column_letter(c)} rows 21:38 nonempty={nonempty} overlap_with_task={overlap}: {col_vals}')

# Infer header row + year columns: row with Task years across columns.
task_years=[ws.cell(10,c).value for c in range(8,13)]
print('\nTask years:', task_years)
for r in range(1,wd.max_row+1):
    matches=[]
    for c in range(1,wd.max_column+1):
        if wd.cell(r,c).value in task_years:
            matches.append(c)
    if matches:
        print(f'Data row {r} matches Task years at columns {[get_column_letter(c) for c in matches]} values {[wd.cell(r,c).value for c in matches]}')
